// modules/library/components/AuthorForm.js
import { useEffect, useState } from "react";
import { authorApi } from "../api/authorApi";
import { useParams, useNavigate } from "react-router-dom";

export default function AuthorForm({ method }) {
  const { id } = useParams();
  const navigate = useNavigate();

  const [form, setForm] = useState({
    first_name: "",
    last_name: "",
    biography: "",
    nationality: "",
    date_of_birth: "",
    website: ""
  });

  useEffect(() => {
    if (method === "edit") {
      authorApi.get(`/${id}`).then((res) => setForm(res.data));
    }
  }, [id]);

  const handleChange = (e) =>
    setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (method === "create") {
      await authorApi.post("/", form);
    } else {
      await authorApi.put(`/${id}`, form);
    }

    navigate("/library/author");
  };

  return (
    <div className="content-header p-4">
      <h3>{method === "create" ? "Add Author" : "Edit Author"}</h3>

      <form onSubmit={handleSubmit} className="mt-3">

        <div className="form-group mb-2">
          <label>First Name *</label>
          <input
            type="text"
            className="form-control"
            name="first_name"
            value={form.first_name}
            onChange={handleChange}
            required
          />
        </div>

        <div className="form-group mb-2">
          <label>Last Name *</label>
          <input
            type="text"
            className="form-control"
            name="last_name"
            value={form.last_name}
            onChange={handleChange}
            required
          />
        </div>

        <div className="form-group mb-2">
          <label>Biography</label>
          <textarea
            className="form-control"
            name="biography"
            value={form.biography}
            onChange={handleChange}
          ></textarea>
        </div>

        <div className="form-group mb-2">
          <label>Nationality</label>
          <input
            type="text"
            className="form-control"
            name="nationality"
            value={form.nationality}
            onChange={handleChange}
          />
        </div>

        <div className="form-group mb-2">
          <label>Date of Birth</label>
          <input
            type="date"
            className="form-control"
            name="date_of_birth"
            value={form.date_of_birth || ""}
            onChange={handleChange}
          />
        </div>

        <div className="form-group mb-2">
          <label>Website</label>
          <input
            type="url"
            className="form-control"
            name="website"
            value={form.website}
            onChange={handleChange}
          />
        </div>

        <button className="btn btn-primary mt-2">Save</button>
      </form>
    </div>
  );
}
